">GIF</a>\r\n        <a class="btn btn-mini" href="?&search=webp">Webp</a>\r\n      </div>\r\n    </div>\r\n    <!-- 按日期-->\r\n    <div class="col-md-2 col-xs-5">\r\n      <form action="" method="get">\r\n        <div class="input-group">\r\n          <span class="input-group-addon fix-border fix-padding"></span>\r\n          <input type="text" class="form-control form-date input-sm" name="date" value="" readonly="readonly">\r\n          <span class="input-group-btn">\r\n            <button type="submit" class="btn btn-primary input-sm">按日期</button>\r\n          </span>\r\n        </div>\r\n      </form>\r\n      <!-- 返回顶部-->\r\n      <div class="btn btn-mini btn-primary btn-back-to-top"><i class="icon icon-arrow-up"></i></div>\r\n    </div>\r\n  </div>\r\n  <link rel="stylesheet" href="/public/static/EasyImage.css">\r\n  <link rel="stylesheet" href="/public/static/viewjs/viewer.min.css">\r\n  <link rel="stylesheet" href="/public/static/zui/lib/bootbox/bootbox.min.css">\r\n  <link rel="stylesheet" href="/public/static/zui/lib/datetimepicker/datetimepicker.min.css">\r\n  <script type="application/javascript" src="/public/static/viewjs/viewer.min.js"></script>\r\n  <script type="application/javascript" src="/public/static/lazyload/lazyload.min.js"></script>\r\n  <script type="application/javascript" src="/public/static/zui/lib/bootbox/bootbox.min.js"></script>\r\n  <script type="application/javascript" src="/public/static/zui/lib/clipboard/clipboard.min.js"></script>\r\n  <script type="application/javascript" src="/public/static/zui/lib/datetimepicker/datetimepicker.min.js"></script>\r\n  <script>\r\n    // viewjs\r\n    new Viewer(document.getElementById('viewjs'), {\r\n      url: 'data-original',\r\n    });\r\n\r\n    // POST 删除提交\r\n    function ajax_post(url, mode = 'delete') {\r\n\r\n      bootbox.confirm({\r\n        message: "确认执行 " + mode + " 操作?",\r\n        buttons: {\r\n          confirm: {\r\n            label: '确定',\r\n            className: 'btn-success'\r\n          },\r\n          cancel: {\r\n            label: '取消',\r\n            className: 'btn-danger'\r\n          }\r\n        },\r\n        callback: function(result) {\r\n          if (result == true) {\r\n            $.post("del.php", {\r\n                url: url,\r\n                mode: mode\r\n              },\r\n              function(data, status) {\r\n                console.log(data)\r\n                let res = JSON.parse(data);\r\n                new $.zui.Messager(res.msg, {\r\n                  type: res.type,\r\n                  icon: res.icon\r\n                }).show();\r\n                // 延时2秒刷新\r\n                window.setTimeout(function() {\r\n                  window.location.reload();\r\n                }, 2000)\r\n              });\r\n          } else {\r\n            new $.zui.Messager("取消 " + mode, {\r\n              type: "primary", // 定义颜色主题 \r\n              icon: "info-sign" // 定义消息图标\r\n            }).show();\r\n          }\r\n        }\r\n      });\r\n    }\r\n\r\n    // 复制url\r\n    var clipboard = new Clipboard('.copy');\r\n    clipboard.on('success', function(e) {\r\n      new $.zui.Messager("复制直链成功", {\r\n        type: "success", // 定义颜色主题 \r\n        icon: "ok-sign" // 定义消息图标\r\n      }).show();\r\n\r\n    });\r\n    clipboard.on('error', function(e) {\r\n      document.querySelector('.copy');\r\n      new $.zui.Messager("复制失败", {\r\n        type: "danger", // 定义颜色主题 \r\n        icon: "exclamation-sign" // 定义消息图标\r\n      }).show();\r\n    });\r\n\r\n    // 取消/全选文件\r\n    function opcheckboxed(objName, type) {\r\n      var objNameList = document.getElementsByName(objName);\r\n      if (null != objNameList) {\r\n        for (var i = 0; i < objNameList.length; i++) {\r\n          if (objNameList[i].checked == true) {\r\n            if (type != 'checkall') { // 非全选\r\n              objNameList[i].checked = false;\r\n            }\r\n          } else {\r\n            if (type != 'uncheckall') { // 非取消全选\r\n              objNameList[i].checked = true;\r\n            }\r\n          }\r\n        }\r\n      }\r\n    }\r\n    // 回收图片\r\n    function recycle_img() {\r\n      bootbox.confirm({\r\n        message: "确认要放入回收站? <br /> 可在可疑图片中恢复!",\r\n        buttons: {\r\n          confirm: {\r\n            label: '确定',\r\n            className: 'btn-success'\r\n          },\r\n          cancel: {\r\n            label: '取消',\r\n            className: 'btn-danger'\r\n          }\r\n        },\r\n        callback: function(result) {\r\n          if (result == true) {\r\n            obj = document.getElementsByName("checkbox");\r\n            check_val = [];\r\n            for (k in obj) {\r\n              //判断复选框是否被选中\r\n              if (obj[k].checked)\r\n                //获取被选中的复选框的值\r\n                check_val.push(obj[k].value);\r\n              console.log(check_val);\r\n            }\r\n            $.post("del.php", {\r\n              'recycle_url_array': check_val\r\n            }, );\r\n            new $.zui.Messager("放入回收站成功", {\r\n              type: "success", // 定义颜色主题 \r\n              icon: "ok-sign" // 定义消息图标\r\n            }).show();\r\n            // 延时2秒刷新\r\n            window.setTimeout(function() {\r\n              window.location.reload();\r\n            }, 1500)\r\n          } else {\r\n            new $.zui.Messager("取消回收", {\r\n              type: "primary", // 定义颜色主题 \r\n              icon: "info-sign" // 定义消息图标\r\n            }).show();\r\n          }\r\n          console.log('是否回收图片: ' + result);\r\n        }\r\n      });\r\n\r\n    }\r\n    // 删除图片\r\n    function delete_img() {\r\n      bootbox.confirm({\r\n        message: "确认要删除?<br />* 删除文件夹后将无法恢复!",\r\n        buttons: {\r\n          confirm: {\r\n            label: '确定',\r\n            className: 'btn-success'\r\n          },\r\n          cancel: {\r\n            label: '取消',\r\n            className: 'btn-danger'\r\n          }\r\n        },\r\n        callback: function(result) {\r\n          if (result == true) {\r\n            obj = document.getElementsByName("checkbox");\r\n            check_val = [];\r\n            for (k in obj) {\r\n              //判断复选框是否被选中\r\n              if (obj[k].checked)\r\n                //获取被选中的复选框的值\r\n                check_val.push(obj[k].value);\r\n              console.log(check_val);\r\n            }\r\n            $.post("del.php", {\r\n                'del_url_array': check_val\r\n              },\r\n              function(data) {\r\n                if (data.search('success') > 0) {\r\n                  new $.zui.Messager("删除成功", {\r\n                    type: "success", // 定义颜色主题 \r\n                    icon: "ok-sign" // 定义消息图标\r\n                  }).show();\r\n                } else {\r\n                  new $.zui.Messager("删除失败 请登录后再删除!", {\r\n                    type: "danger", // 定义颜色主题 \r\n                    icon: "exclamation-sign" // 定义消息图标\r\n                  }).show();\r\n                }\r\n                // 延时2秒刷新\r\n                window.setTimeout(function() {\r\n                  window.location.reload();\r\n                }, 1500)\r\n              });\r\n          } else {\r\n            new $.zui.Messager("取消删除", {\r\n              type: "primary", // 定义颜色主题 \r\n              icon: "info-sign" // 定义消息图标\r\n            }).show();\r\n          }\r\n          console.log('是否删除图片: ' + result);\r\n        }\r\n      });\r\n    }\r\n\r\n    //懒加载\r\n    var lazy = new Lazy({\r\n      onload: function(elem) {\r\n        console.log(elem)\r\n      },\r\n      delay: 300,\r\n    })\r\n\r\n    // 返回顶部\r\n    var back_to_top_button = jQuery('.btn-back-to-top');\r\n    jQuery(window).scroll(function() {\r\n      if (jQuery(this).scrollTop() > 100 && !back_to_top_button.hasClass('scrolled')) {\r\n        back_to_top_button.addClass('scrolled');\r\n\r\n      } else if (jQuery(this).scrollTop() < 100 && back_to_top_button.hasClass('scrolled')) {\r\n        back_to_top_button.removeClass('scrolled');\r\n\r\n      }\r\n    });\r\n    // 返回顶部\r\n    back_to_top_button.click(function() {\r\n      jQuery('html, body').animate({\r\n        scrollTop: 0\r\n      }, 800);\r\n      return false;\r\n    });\r\n\r\n    // 按日期浏览\r\n    $(".form-date").datetimepicker({\r\n      weekStart: 1,\r\n      todayBtn: 1,\r\n      autoclose: 1,\r\n      todayHighlight: 1,\r\n      startView: 2,\r\n      minView: 2,\r\n      forceParse: 0,\r\n      pickerPosition: "top-right",\r\n      format: "yyyy/mm/dd/",\r\n      endDate: new Date() // 只能选当前日期之前\r\n    });\r\n\r\n    // 更改网页标题\r\n    document.title = "图床广场 - 今日上传张 昨日张 - "\r\n  </script>\r\n  